'use strict';
// RiNG의 일반 단골은 이 게임을 위해 만든 인물이다.
const regularStories={
  haru_first:{title:'하루의 첫 단골석',day:12,when:s=>s.regulars.haru>=1,lines:[['하루','안녕하세요. 오늘도 블렌드로 부탁드려요.'],['타키','네. 지난번이랑 같은 걸로 드릴게요.'],['하루','기억해 주셨네요. 공연 기다릴 때 이 자리가 편해서요.'],['타키','출입구가 잘 보이죠. 뜨거우니까 조심하세요.'],['하루','감사합니다. 오늘은 친구도 데려올까 생각 중이에요.'],['타키','그러면 두 분이 앉을 자리도 봐 둘게요.'],['하루','아, 꼭 이 자리가 아니어도 돼요. 친구는 입구에서 헤맬까 봐서요.'],['타키','입구에서 카운터가 바로 보이니까, 여기로 오라고 하시면 돼요.'],['하루','제가 먼저 와 있으면 더 쉽겠네요.'],['타키','네. …아, 공연 시작 전에는 사람이 몰릴 수도 있어요.'],['하루','그럼 조금 일찍 만나기로 해야겠어요. 알려 주셔서 고마워요.'],['타키','네. 커피는 천천히 드세요.']]},
  haru_return:{title:'두 장의 공연표',day:18,when:s=>s.regulars.haru>=2&&s.stories.includes('haru_first'),lines:[['하루','오늘은 친구랑 같이 왔어요. 여기 공연이 처음이래요.'],['타키','그러면 입장 줄은 저쪽에서 서시면 돼요. 시작 전에는 안내 방송도 나와요.'],['하루','다행이다. 제가 설명을 잘 못해서.'],['타키','궁금한 게 있으면 직원한테 물어봐 주세요.'],['하루','네. 커피 마시고 천천히 들어갈게요.'],['하루','친구가 처음 오는 곳에서는 자꾸 길을 잃어서, 제가 먼저 와 있었거든요.'],['타키','아까 입구에서 기다리던 분이 친구분이었군요.'],['하루','네. 카운터가 보이니까 찾기 쉬웠대요.'],['타키','다행이네요. 공연장 문 열리면 여기에서도 보일 거예요.'],['하루','지난번에 알려 주신 자리라서요.'],['타키','…그랬죠. 뜨거우니까 컵 조심하시고요.'],['하루','네. 오늘은 둘 다 안 헤매고 들어갈 수 있겠어요.']]},
  mei_first:{title:'메이가 고르는 케이크',day:13,when:s=>s.regulars.mei>=1&&s.stock.cake>0,lines:[['메이','오늘도 케이크가 있네요. 지난번에 먹은 게 맛있었어요.'],['타키','감사합니다. 오늘은 남은 수량이 메뉴판에 적혀 있어요.'],['메이','그럼 한 조각 부탁드려요. 친구에게도 추천하고 싶은데, 너무 달진 않나요?'],['타키','단맛은 느껴지는데… 잠깐만요. 메뉴 설명을 확인해 볼게요.'],['메이','아, 제가 적힌 걸 못 봤네요.'],['타키','아뇨, 이쪽 글씨가 좀 작아요. 여기 적혀 있어요.'],['메이','커피랑 같이 먹기 좋겠네요. 친구가 쓴 커피를 좋아하거든요.'],['타키','그럼 블렌드도 같이 주문하실래요?'],['메이','오늘은 케이크만 먹고, 다음에 친구랑 같이 올게요.'],['타키','네. 포크는 접시 옆에 놓아 둘게요.'],['메이','감사합니다. 메뉴 설명도 천천히 읽어 볼게요.']]},
  mei_return:{title:'마지막 한 조각의 행방',day:19,when:s=>s.regulars.mei>=2&&s.stock.cake===0&&s.stories.includes('mei_first'),lines:[['메이','아, 오늘은 케이크가 다 팔렸네요.'],['타키','네. 죄송해요. 다른 메뉴는 아직 주문할 수 있어요.'],['메이','괜찮아요. 오늘은 라테로 할게요.'],['타키','네. 다음 공연 전에도 준비할 예정이에요.'],['메이','그럼 그날은 조금 일찍 올게요.'],['메이','지난번에 친구한테 얘기했더니 같이 먹어 보고 싶어 했거든요.'],['타키','아, 그때 말씀하신 분이요.'],['메이','네. 오늘은 시간이 안 맞아서 저 혼자 왔어요.'],['타키','남은 수량을 메뉴판에 더 잘 보이게 적어 둘게요.'],['메이','그러면 들어오자마자 확인할 수 있겠네요.'],['타키','네. 다 팔리면 표시도 바꿔 둘 테니까.'],['메이','좋아요. 오늘 라테도 천천히 마시고 갈게요.']]},
  jun_first:{title:'준의 작은 수첩',day:14,when:s=>s.regulars.jun>=1&&liveDay(),lines:[['준','라테 한 잔 부탁합니다. 공연 시간은 문 앞에서 확인했어요.'],['타키','네. 입장 안내가 나오면 저쪽 문으로 가시면 돼요.'],['준','고맙습니다. 제가 본 공연들을 수첩에 적고 있어서요.'],['타키','많이 보셨나 보네요.'],['준','아직 빈 페이지가 많아요. 천천히 채우려고요.'],['타키','날짜만 적으시는 거예요?'],['준','밴드 이름이랑, 그날 기억하고 싶은 것도 조금요.'],['타키','…나중에 보면 구분이 잘 되겠네요.'],['준','가끔은 이름보다 그날 무대의 소리가 먼저 생각나기도 해요.'],['타키','그럴 때 있죠. 같은 곡이어도 공연마다 다르니까.'],['준','맞아요. 그래서 빠뜨리지 않게 적어 두려고요.'],['타키','라테는 여기 둘게요. 수첩 젖지 않게 조심하세요.']]},
  jun_return:{title:'수첩의 빈 페이지',day:20,when:s=>s.regulars.jun>=2&&s.stories.includes('jun_first'),lines:[['준','지난 공연 날짜를 적어 뒀는데, 밴드 이름을 빠뜨렸네요.'],['타키','공연 포스터가 저쪽에 남아 있어요.'],['준','아, 저기 있군요. 고맙습니다.'],['타키','날짜랑 이름이 작게 적혀 있으니까 가까이서 보셔도 돼요.'],['준','네. 글씨만 적어 갈게요.'],['준','이날 드럼이 시작되기 전에 잠깐 조용했던 것도 기억나네요.'],['타키','…그런 것도 적으세요?'],['준','네. 그다음 소리가 더 크게 들렸거든요.'],['타키','같은 곡이어도 무대마다 조금씩 달라서요.'],['준','그래서 적어 두면 좋더라고요. 포스터 덕분에 빈칸도 채웠네요.'],['타키','다음 공연 안내도 바뀌면 여기에 붙여 둘게요.'],['준','그럼 오면서 확인할게요. 고맙습니다.']]}
};
